import { describe, expect, it } from 'vitest';
import { sequentialIdFactory } from '../ir/ids';
import { emptyProgram, programFromCommands, programFromSpec } from '../ir/program';
import { lineNodeIds, printProgram } from './printTs';

describe('printProgram', () => {
  it('prints an empty program', () => {
    expect(printProgram(emptyProgram())).toBe(
      [
        '// Generated by Wonderbits from program IR v1. Read-only.',
        "import { robot } from 'wonderbits';",
        '',
        'export function main(): void {',
        '  // No steps yet.',
        '}',
        '',
      ].join('\n'),
    );
  });

  it('prints one annotated statement per node', () => {
    const p = programFromCommands(['forward', 'rotateCW', 'rotateCCW'], sequentialIdFactory());
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      export function main(): void {
        robot.forward(); // @node n1
        robot.rotateClockwise(); // @node n2
        robot.rotateCounterClockwise(); // @node n3
      }
      "
    `);
  });

  it('prints blocks as loops and ifs, with the node tag on the opening line', () => {
    const p = programFromSpec(
      [{ repeat: 3, do: ['forward', { if: 'blockedAhead', do: ['rotateCW'], else: [] }] }, { until: 'atFlag', do: [{ if: 'acornAhead', do: ['forward'] }] }],
      sequentialIdFactory(),
    );
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      export function main(): void {
        for (let i = 0; i < 3; i++) { // @node n1
          robot.forward(); // @node n2
          if (robot.blockedAhead()) { // @node n3
            robot.rotateClockwise(); // @node n4
          } else {
            // Nothing inside yet.
          }
        }
        while (!robot.atFlag()) { // @node n5
          if (robot.acornAhead()) { // @node n6
            robot.forward(); // @node n7
          }
        }
      }
      "
    `);
    const ids = lineNodeIds(printProgram(p)).filter((x): x is string => x !== null);
    expect(ids).toEqual(['n1', 'n2', 'n3', 'n4', 'n5', 'n6', 'n7']);
  });

  it('is deterministic and lists every node id exactly once', () => {
    const p = programFromCommands(['forward', 'forward', 'rotateCW', 'forward'], sequentialIdFactory());
    const a = printProgram(p);
    expect(printProgram(structuredClone(p))).toBe(a);
    const ids = lineNodeIds(a).filter((x): x is string => x !== null);
    expect(ids).toEqual(['n1', 'n2', 'n3', 'n4']);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('prints a function beside main and a call as a statement', () => {
    const p = programFromSpec([{ call: 'hop' }, 'forward', { define: 'hop', do: ['forward', 'rotateCW'] }, { define: 'turnAround', do: [] }], sequentialIdFactory());
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      export function main(): void {
        hop(); // @node n1
        robot.forward(); // @node n2
      }

      function hop(): void {
        robot.forward(); // @node n3
        robot.rotateClockwise(); // @node n4
      }

      function turnAround(): void {
        // No steps yet.
      }
      "
    `);
  });

  it('prints When cards as handlers, and gate and wait cards as calls', () => {
    const p = programFromSpec(['wait', { on: 'stepOn:1', do: [{ open: 'a' }] }, { on: 'key:up', do: [{ close: 'b' }] }, { on: 'tick', do: [] }], sequentialIdFactory());
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      export function main(): void {
        robot.wait(); // @node n1
      }

      robot.on('steppedOn', 1, () => { // @node on:stepOn:1
        robot.openGate('a'); // @node n2
      });

      robot.on('keyPressed', 'up', () => { // @node on:key:up
        robot.closeGate('b'); // @node n3
      });

      robot.on('tick', () => { // @node on:tick
        // No steps yet.
      });
      "
    `);
  });

  it('prints memory slots as typed variables, and memory cards as statements', () => {
    const p = programFromSpec(
      [
        { remember: 'count', kind: 'number' },
        { remember: 'way', kind: 'direction', start: 'E' },
        { remember: 'route', kind: 'list', of: 'direction', start: ['E', 'S'] },
        { set: 'way', to: 'facing' },
        { forEach: 'route', as: 'way', do: [{ face: 'way' }, { change: 'count', by: 1 }] },
        { until: 'slot:count=3', do: [{ change: 'count', by: -1 }] },
        { unlock: 'a', with: 'count' },
      ],
      sequentialIdFactory(),
    );
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot, type Direction } from 'wonderbits';

      let count: number = 0;
      let way: Direction = 'right';
      let route: Direction[] = ['right', 'down'];

      export function main(): void {
        way = robot.facing(); // @node n1
        for (way of route) { // @node n2
          robot.face(way); // @node n3
          count += 1; // @node n4
        }
        while (count !== 3) { // @node n5
          count -= 1; // @node n6
        }
        robot.unlock('a', count); // @node n7
      }
      "
    `);
  });

  it('prints grids as arrays of rows, indexed row first, from 0', () => {
    const p = programFromSpec(
      [
        { remember: 'walls', kind: 'grid', of: 'yesNo', start: [[true, false]] },
        { remember: 'wall', kind: 'yesNo' },
        { set: 'wall', to: 'read:walls@ahead' },
        { mark: 'walls', at: 'here', with: 'wall' },
      ],
      sequentialIdFactory(),
    );
    expect(printProgram(p)).toMatchInlineSnapshot(`
      "// Generated by Wonderbits from program IR v1. Read-only.
      import { robot } from 'wonderbits';

      let walls: boolean[][] = [[true, false]];
      let wall: boolean = false;

      export function main(): void {
        wall = walls[robot.ahead().y][robot.ahead().x]; // @node n1
        walls[robot.position().y][robot.position().x] = wall; // @node n2
      }
      "
    `);
  });

  it('prints adding to a list as push, and its length as .length', () => {
    const p = programFromSpec([{ remember: 'seen', kind: 'list', of: 'yesNo' }, { remember: 'n', kind: 'number' }, { push: 'seen', to: 'acornAhead' }, { set: 'n', to: 'length:seen' }], sequentialIdFactory());
    expect(printProgram(p)).toContain('seen.push(robot.acornAhead()); // @node n1');
    expect(printProgram(p)).toContain('n = seen.length; // @node n2');
    expect(printProgram(p)).toContain('let seen: boolean[] = [];');
  });

  it('prints the acorns left on the board as a question for the bird, which sees the whole board', () => {
    const p = programFromSpec([{ remember: 'left', kind: 'number' }, { set: 'left', to: 'acornsLeft' }], sequentialIdFactory());
    expect(printProgram(p)).toContain("import { robot, bird } from 'wonderbits';");
    expect(printProgram(p)).toContain('left = bird.acornsLeft(); // @node n1');
  });

  it('prints a slot in the backpack as loaded in the morning and saved at night', () => {
    const p = programFromSpec([{ remember: 'total', kind: 'number', keep: true }, { remember: 'today', kind: 'number' }, { change: 'total', by: 1 }], sequentialIdFactory());
    const code = printProgram(p);
    expect(code).toContain("import { robot, backpack } from 'wonderbits';");
    expect(code).toContain("let total: number = backpack.load('total', 0);");
    expect(code).toContain('let today: number = 0;');
    expect(code).toContain("robot.on('night', () => { // @node night\n  backpack.save('total', total);\n});");
  });

  it('prints records with an interface for their shape, and their fields with dots', () => {
    const fields = { number: 'number', key: 'yesNo' } as const;
    const p = programFromSpec(
      [
        { remember: 'crates', kind: 'list', of: 'record', shape: 'Crate', fields, start: [{ number: 1, key: false }, { number: 2, key: true }] },
        { remember: 'crate', kind: 'record', shape: 'Crate', fields },
        { remember: 'code', kind: 'number' },
        { forEach: 'crates', as: 'crate', do: [{ if: 'slot:crate.key=yes', do: [{ set: 'code', to: 'field:crate.number' }] }] },
      ],
      sequentialIdFactory(),
    );
    const code = printProgram(p);
    expect(code).toContain('interface Crate {\n  number: number;\n  key: boolean;\n}');
    expect(code).toContain('let crates: Crate[] = [{ number: 1, key: false }, { number: 2, key: true }];');
    expect(code).toContain('let crate: Crate = { number: 0, key: false };');
    expect(code).toContain('if (crate.key) { // @node n2');
    expect(code).toContain('code = crate.number; // @node n3');
  });

  it('prints a team board as a blueprint class and its robots as instances', () => {
    const p = programFromSpec([{ remember: 'steps', kind: 'number' }, { until: 'slot:steps=0', do: ['forward', { change: 'steps', by: -1 }] }], sequentialIdFactory());
    const team = [
      { robot: { x: 0, y: 0, facing: 'E' as const }, goal: { x: 2, y: 0 }, memory: { steps: 2 } },
      { robot: { x: 0, y: 1, facing: 'E' as const }, goal: { x: 3, y: 1 }, memory: { steps: 3 } },
    ];
    const code = printProgram(p, { team });
    expect(code).toContain("import { Robot } from 'wonderbits';");
    expect(code).toContain('class Bot extends Robot {\n  steps: number = 0;\n\n  main(): void {');
    expect(code).toContain('    while (this.steps !== 0) { // @node n1');
    expect(code).toContain('      this.forward(); // @node n2');
    expect(code).toContain('      this.steps -= 1; // @node n3');
    expect(code).toContain("  Object.assign(new Bot(0, 0, 'right'), { steps: 2 }),");
    expect(code).toContain('for (const bot of team) bot.main();');
  });

  it('prints the bird as a place the robot sends out and reads the map under', () => {
    const p = programFromSpec([{ remember: 'bird', kind: 'position' }, { remember: 'walls', kind: 'grid', of: 'yesNo', start: 'board:walls' }, { remember: 'rock', kind: 'yesNo' }, { shift: 'bird', dir: 'E' }, { set: 'rock', to: 'read:walls@bird' }], sequentialIdFactory());
    const code = printProgram(p);
    expect(code).toContain('bird.x += 1; // @node n1');
    expect(code).toContain('rock = walls[bird.y][bird.x]; // @node n2');
  });
});
